{
  "a_sentences": [
    {
      "a_text": "Streitig ist, ob die Vorinstanz Bundesrecht verletzte, indem sie einen Rentenanspruch des Versicherten verneinte.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Im Zentrum steht die Frage, ob sie das Vorliegen eines Revisionsgrunds zu Recht in Abrede stellte.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Nach Art. 17 Abs. 1 ATSG wird die Rente bei einer erheblichen Änderung des Invaliditätsgrades für die Zukunft entsprechend erhöht, herabgesetzt oder aufgehoben.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Liegt ein Revisionsgrund vor, ist der Rentenanspruch umfassend zu prüfen, ohne Bindung an frühere Beurteilungen.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Eine umfassende Prüfung ist erforderlich, wenn eine wesentliche Änderung der tatsächlichen Verhältnisse vorliegt, die geeignet ist, den Invaliditätsgrad zu beeinflussen.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Eine glaubhaft gemachte wesentliche Veränderung der tatsächlichen Umstände, die im strukturierten Beweisverfahren zu einer anderen Beurteilung der rechtlichen Massgeblichkeit der medizinischen Arbeitsfähigkeitsschätzung führt, gilt als Sachverhaltsänderung im Sinne von Art. 17 Abs. 1 ATSG.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz stellte keine Sachverhaltsfeststellungen dazu, ob die geltend gemachten revisionsbegründenden Veränderungen tatsächlich eingetreten sind.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Die Sache wird an die IV-Stelle zurückgewiesen, damit diese die notwendigen Abklärungen trifft.",
      "b_propositions": ["P8"]
    }
  ]
}
